from __future__ import annotations

ADMIN_SCRIPT = 'function adminMetric(label,value){return `<div class="card"><div class="muted">${esc(label)}</div><div class="metric">${esc(value)}</div></div>`}\nasync function adminTab(tab,el,updateUrl=true){if(updateUrl){const p=adminPaths[tab]||\'/admin\';if(location.pathname!==p)history.pushState({adminTab:tab},\'\',p)}document.querySelectorAll(\'#adminTabs button\').forEach(b=>{b.classList.remove(\'primary\');b.classList.add(\'secondary\')});if(el){el.classList.remove(\'secondary\');el.classList.add(\'primary\')}adminContent.innerHTML=\'<div class="card empty">Loading…</div>\';try{if(tab===\'dashboard\'){const d=await api(\'/api/admin/dashboard\');adminContent.innerHTML=`<div class="grid">${adminMetric(\'Total users\',d.users)}${adminMetric(\'Active users · 7d\',d.active_users_7d)}${adminMetric(\'Online nodes\',d.online_nodes)}${adminMetric(\'Operations today\',d.operations_today)}${adminMetric(\'Operations · 30d\',d.operations_30d)}${adminMetric(\'Paid users\',d.paid_users)}</div><div class="card" style="margin-top:16px"><h3>Recent activity</h3>${d.recent.length?\'<table class="table"><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Target</th></tr></thead><tbody>\'+d.recent.map(r=>`<tr><td>${esc(timefmt(r.created_at))}</td><td>${esc(r.email||\'—\')}</td><td>${esc(r.action)}</td><td>${esc(r.target||\'—\')}</td></tr>`).join(\'\')+\'</tbody></table>\':\'<div class="empty">No activity.</div>\'}</div>`}else if(tab===\'users\'){const d=await api(\'/api/admin/users\');adminContent.innerHTML=`<div class="toolbar"><input id="adminUserSearch" class="input" placeholder="Search email or name"><button class="btn secondary" onclick="adminSearchUsers()">Search</button></div><div id="adminUsersTable">${renderAdminUsers(d.users)}</div>`}else if(tab===\'usage\'){const d=await api(\'/api/admin/usage\');adminContent.innerHTML=`<div class="grid">${adminMetric(\'Requests · 30d\',d.requests_30d)}${adminMetric(\'Operations · 30d\',d.operations_30d)}${adminMetric(\'Execution · 30d\',Math.round(d.execution_seconds_30d)+\'s\')}${adminMetric(\'Success rate\',d.success_rate+\'%\')}${adminMetric(\'Failed · 30d\',d.errors_30d)}${adminMetric(\'Files / Shell / Git\',(d.by_tool.files||0)+\' / \'+(d.by_tool.shell||0)+\' / \'+(d.by_tool.git||0))}</div><div class="card" style="margin-top:16px"><h3>Top users · 30d</h3><table class="table"><thead><tr><th>User</th><th>Operations</th></tr></thead><tbody>${d.top_users.map(r=>`<tr><td>${esc(r.email)}</td><td>${esc(r.n)}</td></tr>`).join(\'\')}</tbody></table></div>`}else if(tab===\'nodes\'){const d=await api(\'/api/admin/nodes\');adminContent.innerHTML=d.nodes.length?`<table class="table"><thead><tr><th>Node</th><th>Platform</th><th>Status</th><th>Allowed folders</th><th>Last seen</th></tr></thead><tbody>${d.nodes.map(n=>`<tr><td><b>${esc(n.name)}</b><div class="muted">${esc(n.node_id)}</div></td><td>${esc(n.platform)}</td><td><span class="badge ${n.online?\'online\':\'offline\'}">${n.online?\'Online\':\'Offline\'}</span></td><td>${esc(n.allowed_folder_count)}</td><td>${esc(timefmt(n.updated_at))}</td></tr>`).join(\'\')}</tbody></table>`:\'<div class="card empty">No nodes.</div>\'}else if(tab===\'operations\'){const d=await api(\'/api/admin/operations?limit=300\');adminContent.innerHTML=`<div class="toolbar"><input id="adminOpUser" class="input" placeholder="User"><input id="adminOpAction" class="input" placeholder="Tool / action"><button class="btn secondary" onclick="adminFilterOps()">Filter</button></div><div id="adminOpsTable">${renderAdminOps(d.operations)}</div>`}else if(tab===\'subscriptions\'){const d=await api(\'/api/admin/subscriptions\');adminContent.innerHTML=`<table class="table"><thead><tr><th>User</th><th>Plan</th><th>Status</th><th>Expansion</th><th>Provider</th><th>Renews</th></tr></thead><tbody>${d.subscriptions.map(s=>`<tr><td>${esc(s.email)}</td><td>${esc(s.plan)}</td><td>${esc(s.status)}</td><td>${esc(s.expansion_quantity||0)}</td><td>${esc(s.billing_provider||\'—\')}</td><td>${esc(timefmt(s.current_period_end||s.ends_at))}</td></tr>`).join(\'\')}</tbody></table>`}else if(tab===\'system\'){const d=await api(\'/api/admin/system\');adminContent.innerHTML=`<div class="grid">${adminMetric(\'Gateway\',d.gateway)}${adminMetric(\'Database\',d.database)}${adminMetric(\'Online nodes\',d.online_nodes)}${adminMetric(\'Total nodes\',d.total_nodes)}${adminMetric(\'Users\',d.users)}${adminMetric(\'Server time\',new Date(d.server_time*1000).toLocaleString())}</div>`}}catch(e){adminContent.innerHTML=`<div class="error">${esc(e.message)}</div>`}}\nfunction renderAdminUsers(rows){return rows.length?\'<table class="table"><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Plan</th><th>Nodes</th><th>Ops 30d</th><th>Last active</th></tr></thead><tbody>\'+rows.map(u=>`<tr style="cursor:pointer" onclick="showAdminUser(\'${u.id}\')"><td><b>${esc(u.email)}</b><div class="muted">${esc(u.name||\'\')}</div></td><td>${esc(u.role)}</td><td>${esc(u.status)}</td><td>${esc(u.plan)}</td><td>${esc(u.node_count)}</td><td>${esc(u.operations_30d)}</td><td>${esc(timefmt(u.last_login_at))}</td></tr>`).join(\'\')+\'</tbody></table>\':\'<div class="card empty">No users.</div>\'}\nasync function adminSearchUsers(){const d=await api(\'/api/admin/users?q=\'+encodeURIComponent(adminUserSearch.value));adminUsersTable.innerHTML=renderAdminUsers(d.users)}\nfunction renderAdminOps(rows){return rows.length?\'<table class="table"><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Target</th><th>Status</th></tr></thead><tbody>\'+rows.map(o=>`<tr><td>${esc(timefmt(o.created_at))}</td><td>${esc(o.email||\'—\')}</td><td>${esc(o.action)}</td><td>${esc(o.target||\'—\')}</td><td>${esc(o.status)}</td></tr>`).join(\'\')+\'</tbody></table>\':\'<div class="card empty">No operations.</div>\'}\nasync function adminFilterOps(){const q=new URLSearchParams({limit:\'300\'});if(adminOpUser.value)q.set(\'user\',adminOpUser.value);if(adminOpAction.value)q.set(\'action\',adminOpAction.value);const d=await api(\'/api/admin/operations?\'+q);adminOpsTable.innerHTML=renderAdminOps(d.operations)}\nasync function saveAdminUser(id){await api(\'/api/admin/users/\'+encodeURIComponent(id),{method:\'PUT\',body:JSON.stringify({status:adminDetailStatus.value,plan:adminDetailPlan.value,bonus_requests:+adminDetailBonus.value||0})});toast(\'User updated\');await showAdminUser(id)}\nasync function showAdminUser(id){const d=await api(\'/api/admin/users/\'+encodeURIComponent(id));const u=d.user;adminUserDetail.innerHTML=`<h3>${esc(u.email)}</h3><div class="grid">${adminMetric(\'Plan\',d.subscription.plan)}${adminMetric(\'Requests\',d.entitlements.requests_used+\' / \'+d.entitlements.request_limit)}${adminMetric(\'Nodes\',d.entitlements.nodes_used+\' / \'+d.entitlements.node_limit)}${adminMetric(\'AI accounts\',d.entitlements.ai_accounts_used+\' / \'+d.entitlements.ai_account_limit)}${adminMetric(\'Expansion packs\',d.entitlements.expansion_quantity)}${adminMetric(\'Operations · 30d\',d.usage.last30||0)}</div><div class="card" style="margin-top:14px"><div class="row"><div><b>Role</b><div>${esc(u.role)}</div></div><div><b>Status</b><select id="adminDetailStatus"><option value="active" ${u.status===\'active\'?\'selected\':\'\'}>active</option><option value="disabled" ${u.status===\'disabled\'?\'selected\':\'\'}>disabled</option></select></div><div><b>Plan</b><select id="adminDetailPlan"><option value="free" ${d.subscription.plan===\'free\'?\'selected\':\'\'}>free</option><option value="pro" ${d.subscription.plan===\'pro\'?\'selected\':\'\'}>pro</option><option value="pro_plus" ${d.subscription.plan===\'pro_plus\'?\'selected\':\'\'}>pro_plus</option></select></div><div><b>Bonus Requests</b><input id="adminDetailBonus" class="input" type="number" min="0" value="${esc(d.entitlements.bonus_requests||0)}"></div></div><div class="actions"><button class="btn primary" onclick="saveAdminUser(\'${u.id}\')">Save account</button></div></div><h3 style="margin-top:18px">Nodes</h3>${d.nodes.length?\'<table class="table"><tbody>\'+d.nodes.map(n=>`<tr><td>${esc(n.name)}</td><td>${esc(timefmt(n.updated_at))}</td></tr>`).join(\'\')+\'</tbody></table>\':\'<div class="empty">No nodes.</div>\'}<h3 style="margin-top:18px">Recent operations</h3>${renderAdminOps(d.operations.map(o=>({...o,email:u.email,status:(o.details||{}).status||\'success\'})))}`;adminUserModal.classList.remove(\'hidden\')}\nif(WEB_LANG===\'zh\'){localizeWeb();new MutationObserver(mutations=>{for(const m of mutations){for(const n of m.addedNodes){if(n.nodeType===Node.ELEMENT_NODE)localizeWeb(n);else if(n.nodeType===Node.TEXT_NODE&&WEB_ZH[n.nodeValue.trim()])n.nodeValue=WEB_ZH[n.nodeValue.trim()]}}}).observe(document.body,{childList:true,subtree:true})}\nboot();\n</script>\n</body></html>'
